// Auto-generated Pivnick seller-side playbook data. Do not hand-edit.
// Extracted from the Pivnick MCP: get_rubric(seller), get_policy_bundle, read_attorney_preferences.

export const RUBRIC_SELLER = {"side": "seller", "source": "Rubric_SELLER (6).docx", "positions": [{"id": 1, "topic": "Notices", "rule": "Add the attorney's copy-to under Seller's notice address. On seller side: HARD COPY (full firm block + Attn + address). Rob's house rule: do NOT include email on seller contracts on first pass — try to make it harder for buyer. Add email later if buyer asks. Use the attorney named in intake Q0.", "applies_when": "Every deal.", "deal_specific": false, "skip": false, "marked_by": ["Rob Pivnick"]}, {"id": 2, "topic": "Reps — knowledge qualifier", "rule": "Tie Seller's knowledge to a single named individual; strip imputation. Verbatim tail: \"without duty of inquiry or the imputation of knowledge from any other party or source.\" ALSO add anti-sandbagging language: if Buyer knows something before DD ends, cannot use it later as a claim; if Buyer closes knowing something, cannot make a claim for it after closing.", "applies_when": "The draft's knowledge qualifier is broad (\"Seller's knowledge,\" no named individual, no duty-of-inquiry limit).", "deal_specific": false, "skip": false, "marked_by": ["Jordan Bailey", "Rob Pivnick"]}, {"id": 3, "topic": "Reps — survival", "rule": "On Pivnick's seller form (which has no survival), keep no-survival language: \"As of the Effective Date and as of Closing, but not surviving Closing.\" When responding to a buyer-provided form with survival, drop it to 90-180 days on first pass (market is 6-12 months). Include anti-sandbagging + materiality scrape.", "applies_when": "The draft has Seller's representations surviving Closing (a buyer-form default).", "deal_specific": false, "skip": false, "marked_by": ["Jordan Bailey", "Rob Pivnick"]}, {"id": 4, "topic": "Reps — scope", "rule": "Where Seller has to give a property-touching rep, prefix it with \"Seller has not received any written notice of…\" — notice-only reps. In an as-is sale, STRIKE all reps Buyer puts in the form — but use \"Intentionally Deleted\" instead of deleting outright (preserves numbering).", "applies_when": "A property-touching rep is flat or absolute (no knowledge/notice qualifier).", "deal_specific": false, "skip": false, "marked_by": ["Rob Pivnick"]}, {"id": 5, "topic": "AS IS", "rule": "When Seller has NO construction work in the deal: insert the full ALL CAPS AS IS block, DTPA waiver under Tex. Bus. & Com. Code §17.41, and federal environmental statute laundry list (CERCLA, RCRA, etc.). IF the deal is NOT in Texas, use the more general language from Pivnick's seller-side form PSA — not the Texas-specific block.", "applies_when": "Seller has NO construction work in the deal (no Seller's Work, no Exhibit D workletter).", "deal_specific": false, "skip": false, "marked_by": ["Jordan Bailey", "Rob Pivnick"]}, {"id": 6, "topic": "Remedies — strip \"any and all remedies\" language", "rule": "If draft gives Buyer \"any and all remedies at law or in equity\" on Seller default, delete the broad language and restructure into a sole-remedy framework. Add a 60-day filing deadline on any specific-performance right: \"(an action for which must be filed within sixty (60) days failing which Purchaser shall be deemed to have waived the same).\"", "applies_when": "The draft gives Buyer \"any and all remedies at law or in equity\" on Seller default.", "deal_specific": false, "skip": false, "marked_by": []}, {"id": 7, "topic": "Remedies — cap on Buyer's out-of-pocket recovery", "rule": "FIRST PASS: STRIKE the Buyer-out-of-pocket recovery language entirely (don't engage on a cap — just remove). Negotiate later. Don't accept a $50K cap on first pass — that's a fallback, not an opening position.", "applies_when": "The draft exposes Seller to Buyer's out-of-pocket costs on Seller default.", "deal_specific": false, "skip": false, "marked_by": ["Jordan Bailey", "Rob Pivnick"]}, {"id": 8, "topic": "Remedies — preserve surviving indemnities on termination", "rule": "Insert the surviving-indemnities carve-out inside termination-rights clause: \"excepting any indemnities specifically surviving such termination.\" This should ONLY reach Buyer indemnities (diligence/inspection activities) — Seller should not have surviving indemnities.", "applies_when": "The draft's termination clause does not carve out surviving indemnities, so they would get wiped out when the contract is terminated.", "deal_specific": false, "skip": false, "marked_by": ["Jordan Bailey"]}, {"id": 9, "topic": "Title — Seller silence deemed decline", "rule": "Install Title cure timeline: Seller has 10 days to respond to Buyer's objections; Seller silence = deemed declination to cure. Buyer then has 10 days to terminate; Buyer silence = deemed waiver. Add: any Seller election to cure must be a formal letter on letterhead (avoid argument that random email = agreement to cure).", "applies_when": "The draft's title mechanic defaults buyer-favorable (e.g., Seller silence = deemed cure, or Buyer silence = waiver of objection).", "deal_specific": false, "skip": false, "marked_by": ["Will Bassham"]}, {"id": 10, "topic": "Title — gap coverage", "rule": "Replace title-company-drafted gap indemnity with the standard \"so-called 'gap affidavit'.\"", "applies_when": "The draft requires Seller to execute a title-company-drafted indemnity agreement for gap coverage.", "deal_specific": false, "skip": false, "marked_by": []}, {"id": 11, "topic": "Inspection Period — strip day-for-day extension", "rule": "If draft has day-for-day Inspection Period tolling for late Seller deliveries, STRIKE it. Inspection Period runs from Effective Date regardless of Seller delivery timing. (Rob's note: buyers usually don't include this — we're the rare breed.)", "applies_when": "The draft has day-for-day tolling of the Inspection Period for late Seller deliveries.", "deal_specific": false, "skip": false, "marked_by": ["Rob Pivnick"]}, {"id": 12, "topic": "Inspection Period — no duty to create", "rule": "If the diligence list is open-ended, scope Seller's delivery obligation to documents already in Seller's possession AND carve out privileged or proprietary documents. Verbatim: \"but only if such documents exist and are currently in Seller's possession\" + privileged/proprietary carve-out.", "applies_when": "The draft's diligence list is open-ended (Seller owes whatever Buyer asks for).", "deal_specific": false, "skip": false, "marked_by": ["Jordan Bailey", "Rob Pivnick"]}, {"id": 13, "topic": "Inspection Period — Buyer indemnity fair-notice", "rule": "When Buyer is doing physical inspection and the indemnity is narrow, expand Buyer's indemnity in ALL CAPS to reach Seller's own negligence and strict liability: \"WHETHER ARISING WHOLLY OR IN PART FROM THE NEGLIGENCE OR STRICT LIABILITY OF SELLER.\" Add COI requirement (each vendor, not just Buyer). NOTE: this is aggressive — if Buyer has already carved this out, do NOT strike the carve-out (we'll concede).", "applies_when": "The draft has a narrow Buyer indemnity that doesn't reach Seller's own negligence. Buyer is doing physical inspection.", "deal_specific": false, "skip": false, "marked_by": ["Jordan Bailey", "Rob Pivnick"]}, {"id": 14, "topic": "Force Majeure", "rule": "If Buyer adds Force Majeure to the PSA, STRIKE IT ALTOGETHER — FM has no place in PSAs (concept belongs in leases). Don't engage on a financial-incapacity carve-out; just remove the whole FM clause.", "applies_when": "The draft's Force Majeure clause lacks a financial-incapacity carve-out, or it lets Force Majeure toll monetary-payment obligations.", "deal_specific": false, "skip": false, "marked_by": ["Rob Pivnick"]}, {"id": 15, "topic": "Earnest Money", "rule": "Flip to seller-form Earnest Money structure: single-lump deposit, non-interest-bearing, $200 Independent Consideration, self-executing termination if Buyer fails to fund within 3 business days. (Two-tier is deal-specific — never default to it.)", "applies_when": "The draft has the buyer-form Earnest Money structure: two-tier deposit, interest-bearing to Buyer, $100 Independent Consideration.", "deal_specific": false, "skip": false, "marked_by": ["Rob Pivnick"]}, {"id": 16, "topic": "Brokers", "rule": "Add the closes-or-nothing broker qualifier verbatim: \"if and only if the transaction closes but not otherwise.\"", "applies_when": "The draft has a Seller broker commission obligation without the closes-or-nothing qualifier.", "deal_specific": false, "skip": false, "marked_by": []}, {"id": 17, "topic": "1031 Exchange", "rule": "If draft has 1031 cooperation clause missing any of three qualifiers, insert the missing one(s): (i) no additional cost or liability to non-exchanging party; (ii) Agreement not modified; (iii) non-exchanging party not required to hold title to other property. If all three already present, leave alone.", "applies_when": "The draft has a 1031 cooperation clause missing any of these three qualifiers.", "deal_specific": false, "skip": false, "marked_by": []}, {"id": 18, "topic": "Casualty", "rule": "If draft gives Buyer unqualified casualty termination, insert a dollar materiality threshold + 10-business-day deemed-acceptance window after Seller's notice.", "applies_when": "The draft gives Buyer an unqualified termination right on casualty (no materiality floor, no deemed acceptance).", "deal_specific": false, "skip": false, "marked_by": []}, {"id": 19, "topic": "Consequential damages waiver — standalone", "rule": "Break consequential-damages waiver out as a standalone sentence: \"Neither party shall ever be liable for consequential, special, punitive or exemplary damages.\" Do NOT fight Buyer's carve-out for fraud, intentional misrepresentation, or where specific performance is unavailable — concede.", "applies_when": "The consequential-damages waiver is fused into casualty language instead of standing on its own.", "deal_specific": false, "skip": false, "marked_by": ["Jordan Bailey"]}, {"id": 20, "topic": "Assignment", "rule": "Strip free-assignment language. Require Seller's prior written consent in sole and absolute discretion FOR NON-AFFILIATED BUYER PARTIES ONLY. Affiliate transfers are OK so long as Buyer stays on the hook. No release of Buyer. Add reliance recital on Buyer's identity and creditworthiness.", "applies_when": "The draft allows free assignment or has affiliate/estate-planning carve-outs from Seller's consent.", "deal_specific": false, "skip": false, "marked_by": ["Rob Pivnick"]}, {"id": 21, "topic": "Permitting Period — 45-day Seller cure", "rule": "DEAL-SPECIFIC: When the deal has a permitting period with Buyer termination rights, insert a 45-day Seller cure window before Buyer can terminate for a permits failure.", "applies_when": "The deal has a permitting period with Buyer termination rights.", "deal_specific": true, "skip": false, "marked_by": ["Rob Pivnick"]}, {"id": 22, "topic": "Signature block — Authorized Signatory", "rule": "Replace Seller signature-block title (\"Manager\" / \"Managing Member\" / \"President\") with \"Authorized Signatory\" — keeps alter-ego / LLC-veil protections clean. Rob applies this on everything. Do NOT apply to Title Company's own signature block.", "applies_when": "The Seller signature block has \"Manager\" / \"Managing Member\" / \"President\" as the title.", "deal_specific": false, "skip": false, "marked_by": ["Rob Pivnick"]}, {"id": 23, "topic": "Effective Date — Title Company deposit convention", "rule": "On SELLER side, Effective Date = the last date signed by Buyer or Seller (NOT Title Company deposit — that convention is for BUYER side). Use last-signature convention here.", "applies_when": "The draft uses the buyer-form \"last party to sign\" convention for the Effective Date.", "deal_specific": false, "skip": false, "marked_by": ["Rob Pivnick"]}, {"id": 24, "topic": "Confidentiality", "rule": "Make confidentiality mutual. Add a disclaimer that Seller makes no representations about completeness or accuracy of Site Information delivered. On return: originals returned; copies deleted or destroyed.", "applies_when": "The confidentiality clause is one-sided, or has no disclaimer on completeness of Site Information.", "deal_specific": false, "skip": false, "marked_by": ["Will Bassham"]}, {"id": 25, "topic": "No Recordation", "rule": "Insert a No Recordation section: prohibit Buyer from recording a memorandum of the PSA against title. Self-help via limited power of attorney if Buyer breaches. Apply every deal.", "applies_when": "Every deal.", "deal_specific": false, "skip": false, "marked_by": []}, {"id": 26, "topic": "Texas Statutory Disclosures (Schedule 27.1)", "rule": "TEAM DISAGREEMENT — flag in cover memo: Rob's view is Schedule 27.1 statutory notices are RAW-LAND ONLY. Jordan's view is they apply to developed and operating properties too. Default: add only the notices that are specifically triggered for the parcel; ASK when the parcel type is mixed.", "applies_when": "Every Texas seller-side deal (specific notices triggered by the parcel).", "deal_specific": false, "skip": false, "marked_by": ["Jordan Bailey", "Rob Pivnick"]}, {"id": 27, "topic": "Alter Ego / SPE protection", "rule": "When Seller is a special-purpose entity (SPE) or subsidiary with affiliates, officers, or managers to insulate, insert an Alter Ego / SPE protection section: alter-ego waiver + affiliate protection + fee-shifting if a derivative claim is asserted. Cap recourse to the Seller entity; for pre-Closing matters, cap recourse to sale proceeds.", "applies_when": "Seller is a special-purpose entity (SPE) or subsidiary with affiliates, officers, or managers to insulate from derivative claims.", "deal_specific": false, "skip": false, "marked_by": []}, {"id": 28, "topic": "Declaration Estoppels — preserve Seller's three-qualifier fallback", "rule": "NEVER offer this up on initial draft. Only insert if Buyer adds Declaration Estoppels — then preserve the three-qualifier fallback: commercially reasonable efforts + no non-de-minimis expense + Seller-certification fallback if third parties won't sign.", "applies_when": "Seller owns adjacent property bound by an REA or declaration, AND the draft has a Declaration Estoppel delivery obligation.", "deal_specific": false, "skip": false, "marked_by": ["Rob Pivnick"]}, {"id": 29, "topic": "REA execution at Closing (adjacent property)", "rule": "DEAL-SPECIFIC: Don't add REA execution as a closing condition automatically. Only when Seller owns adjacent property and the REA needs to be executed at/before Closing. Buyer approves the form during Inspection Period, not at Closing table.", "applies_when": "Seller owns adjacent property AND the REA needs to be executed at or before Closing.", "deal_specific": true, "skip": false, "marked_by": ["Rob Pivnick"]}, {"id": 30, "topic": "Financing contingency — Seller pushback", "rule": "DEAL-SPECIFIC: Don't add financing-contingency pushback automatically. If applicable, narrow the contingency: define loan parameters (LTV, rate, amortization). Require application payment / submission critical path. Flag for live discussion.", "applies_when": "The opposing draft contains a financing contingency giving Buyer the right to terminate if Buyer cannot obtain a loan.", "deal_specific": true, "skip": false, "marked_by": ["Rob Pivnick"]}, {"id": 31, "topic": "Repurchase option / reverter — control the recorded memorandum", "rule": "DEAL-SPECIFIC: Rare. When applicable: preserve Seller's control over the recorded memorandum form; tie release of reverter to a specific construction-completion milestone (not Buyer's unilateral certification).", "applies_when": "Buyer's draft includes a Seller repurchase option or reverter, AND gives Buyer the unilateral right to terminate the recorded memorandum once construction starts.", "deal_specific": true, "skip": false, "marked_by": ["Jordan Bailey", "Rob Pivnick"]}, {"id": 32, "topic": "No-MAC closing condition — strike", "rule": "Strike the no-MAC closing condition. But use \"Intentionally Deleted\" — DON'T delete the section number. Seller does not accept a MAC condition on commercial PSA — Inspection Period is Buyer's window to find problems.", "applies_when": "The opposing draft gives Buyer a no-material-adverse-change closing condition.", "deal_specific": false, "skip": false, "marked_by": ["Rob Pivnick"]}, {"id": 33, "topic": "Utilities — strip \"at Seller's expense\"", "rule": "DEAL-SPECIFIC: When draft requires Seller to stub utilities \"at Seller's expense\" on raw-land, strike \"at Seller's expense.\" Where the price clearly wasn't negotiated to absorb utility-extension cost, also delete the entire utility-stubbing covenant.", "applies_when": "The opposing draft requires Seller to stub utilities to the pad or boundary \"at Seller's expense\" on a raw-land deal.", "deal_specific": true, "skip": false, "marked_by": ["Rob Pivnick"]}, {"id": 34, "topic": "Property definition — strip minerals / water / air rights", "rule": "[LEAVE ALONE — TEAM CONSENSUS] Do NOT strip the expanded Property definition (minerals, water, air, riparian, solar) unless client has specifically told us otherwise.", "applies_when": "The opposing draft expands the defined term \"Property\" to reach minerals, water rights, riparian rights, air rights, solar rights.", "deal_specific": false, "skip": true, "marked_by": ["Rob Pivnick", "Will Bassham"]}, {"id": 35, "topic": "Restore \"gross\" in gross-negligence carve-outs", "rule": "If a gross-negligence carve-out has had \"gross\" deleted in the opposing draft, restore it as a tracked change. Texas market practice has the carve-out reach gross negligence, not ordinary negligence.", "applies_when": "The opposing draft has deleted \"gross\" from a gross-negligence carve-out, leaving only \"negligence.\"", "deal_specific": false, "skip": false, "marked_by": []}, {"id": 36, "topic": "Third-party ROFR on the Property", "rule": "Strip any Buyer-side \"Inspection Period shall not commence until ROFR waiver is received\" tolling. Seller's obligation is limited to notifying the ROFR holder — Seller is not liable if the holder fails to waive.", "applies_when": "The property is subject to a third-party right of first refusal.", "deal_specific": false, "skip": false, "marked_by": ["Rob Pivnick"]}, {"id": 38, "topic": "HOA / POA — resist Association financial reps", "rule": "Strike the HOA / POA financial-reps requirement (use \"Intentionally Deleted\"). Seller doesn't stand behind HOA finances or governance.", "applies_when": "The opposing draft requires Seller to rep on the HOA or POA's financial condition, special-assessment history, or architectural-review status.", "deal_specific": false, "skip": false, "marked_by": ["Rob Pivnick"]}, {"id": 39, "topic": "Tenanted / NNN deal — proration handling", "rule": "On NNN deals where tenant pays directly: strike tax proration, strike proration of delinquent rent and pass-throughs, credit security deposits against Purchase Price. Apply only on single-tenant NNN with tenant actually paying directly.", "applies_when": "The property is income-producing with NNN leases (tenant pays taxes, insurance, CAM directly).", "deal_specific": false, "skip": false, "marked_by": ["Rob Pivnick"]}, {"id": 40, "topic": "Lease-termination requirement — narrow", "rule": "DEAL-SPECIFIC, flag for live discussion: when Buyer's draft requires Seller to terminate existing leases before Closing with Buyer self-help, narrow the termination obligation to named leases only, strip Buyer's self-help credit, cap Seller's cost exposure.", "applies_when": "The opposing draft requires Seller to terminate existing leases before Closing, with Buyer self-help rights.", "deal_specific": true, "skip": false, "marked_by": ["Rob Pivnick"]}, {"id": 41, "topic": "Earnest Money — non-estate-property recital (§3.3)", "rule": "Add a Buyer Acknowledgement subsection stating the Earnest Money does not constitute property of Buyer's estate under §541 of Title 11 U.S. Code or substantially similar state law.", "applies_when": "The draft does not contain a Buyer acknowledgement that the Earnest Money is not estate property.", "deal_specific": false, "skip": false, "marked_by": ["Jordan Bailey"]}, {"id": 42, "topic": "Financing — No Financing Contingency carve (§4.1)", "rule": "Insert a new subsection (c) under §4.1 stating Buyer's obligations are not conditioned on Buyer's ability to obtain financing. Hard-locks the deal as all-cash from Seller's perspective.", "applies_when": "The draft does not contain an express no-financing-contingency recital under §4.1 or Purchase Price provisions.", "deal_specific": false, "skip": false, "marked_by": ["Jordan Bailey"]}, {"id": 43, "topic": "Title — Seller-can-convey fallback (§7.3)", "rule": "Add a 'Title as Seller Can Convey' subsection: Buyer may at any time accept such title as Seller can convey, without reduction in Purchase Price, credit, or claim. Acceptance of the Deed is a waiver of unsatisfied Permitted Exceptions.", "applies_when": "The draft's title cure mechanic does not include a Seller-can-convey fallback for the Buyer.", "deal_specific": false, "skip": false, "marked_by": ["Jordan Bailey"]}, {"id": 44, "topic": "Buyer Conditions tightening (§12)", "rule": "Tighten Buyer's Conditions: (i) limit the rep-truth condition to Material Breach, (ii) recast title-policy condition as Title Company committed to issue (not Buyer received), (iii) cabin closing-deliverables condition to documents Seller is obligated to deliver under §17.1, (iv) clean failure-of-conditions cross-reference.", "applies_when": "The draft's §12 Buyer's Conditions are flat absolute or contain buyer-form-default mechanics.", "deal_specific": false, "skip": false, "marked_by": ["Jordan Bailey"]}, {"id": 45, "topic": "Seller Conditions cleanup (§13)", "rule": "On §13 Seller's Conditions, anchor Buyer rep truth to Closing Date and add cross-reference cleanups: (i) Buyer reps true 'as if made on the Closing Date'; (ii) recast Buyer-performance to 'on or before the Closing Date'; (iii) tighten Buyer-deliverables to three numbered prongs.", "applies_when": "The draft's §13 Seller's Conditions has buyer-form-default flat phrasing.", "deal_specific": false, "skip": false, "marked_by": ["Jordan Bailey"]}, {"id": 46, "topic": "Deliveries scrubbing (§17.1)", "rule": "Walk §17.1(a)-(h) Seller's Deliverables and tighten: fix exhibit cross-references, recast to 'One (1) original' for each deliverable, condition General Assignment delivery on contracts/intangibles existing, strip 'no-change affidavit' and survey-deletion language from owner's affidavit. Use 'Intentionally Deleted' to preserve numbering when removing.", "applies_when": "Every seller-side deal — §17.1 has a deliverables list.", "deal_specific": false, "skip": false, "marked_by": ["Jordan Bailey"]}], "leave_alone": [{"id": 1, "item": "Severability clause", "rule": "Do not redline — market-standard, no Seller-protective edit available."}, {"id": 2, "item": "Counterparts / electronic signatures", "rule": "Do not redline — already enforceable under Texas UETA and federal ESIGN."}, {"id": 3, "item": "Governing law (Texas) + venue (Texas state court)", "rule": "Do not change — deal is in Texas."}, {"id": 4, "item": "Mutual jury waiver", "rule": "Do not redline — enforceable under Texas law when conspicuous; bench trials favor sophisticated parties."}, {"id": 5, "item": "Notice mechanics", "rule": "Do not redline delivery mechanics — market-standard. Only edit is adding firm copy-to per Position 1."}, {"id": 6, "item": "Merger / integration clause", "rule": "Do not redline — standard and protective for both sides."}, {"id": 7, "item": "No-oral-waiver clause", "rule": "Do not redline — Seller-protective as drafted."}, {"id": 8, "item": "Recitals", "rule": "Do not redline unless fixing factual errors (wrong party name, wrong property description)."}, {"id": 9, "item": "Exhibit A — Legal Description", "rule": "Do not redline. Survey/title matter; title company catches errors."}, {"id": 10, "item": "Prorations and closing adjustments", "rule": "Do not redline math — market-standard and symmetric."}, {"id": 11, "item": "Signature block order (Seller signs first)", "rule": "Do not redline unless the opposing draft flipped it."}, {"id": 12, "item": "Environmental statute citations", "rule": "Do not narrow statute citations inside the \"Environmental Laws\" defined term."}, {"id": 13, "item": "Environmental covenants when Seller's Work includes remediation", "rule": "Do not redline — negotiated business terms, not boilerplate."}, {"id": 14, "item": "1031 Exchange clause when all three qualifiers present", "rule": "Do not redline when all three qualifiers are already verbatim."}, {"id": 15, "item": "Exhibit and schedule numbering, headers, formatting", "rule": "Do not renumber or rework — breaks cross-references."}, {"id": 16, "item": "Order and structure of the Definitions section", "rule": "Do not reorder defined terms — only edit substance when wording is directly harmful to Seller."}, {"id": 17, "item": "Title Company designation", "rule": "Do not auto-insert a specific Title Company. FLAG ONLY if the draft names a company the client has not approved. NEVER write a specific firm name verbatim."}]} as const;

export const POLICY_SELLER = {"seller_hard_blocks": ["No buyer mineral / water / property-scope expansion.", "No buyer day-for-day diligence toll by default.", "No broad buyer financing/zoning/permit contingency.", "No broad buyer remedy menu, uncapped costs, or open-ended specific performance.", "No new guaranty, joinder, holdback, or net-worth covenant.", "No buyer-favorable tax/CAM/rent credit numbers by assumption.", "No statutory notice insertion unless triggered and seller-favorable.", "No 'Authorized Signatory' on Purchaser/Buyer/Assignee/Grantee/Escrow/Title/Tenant/Lender/Broker/Notary blocks.", "No proposing deletion of materiality or MAE qualifier.", "Knowledge runs only to Seller's named individual — never to 'third party' matters."], "shared_blocks": ["Do not invent facts.", "Do not put cover memo, QA notes, or run logs in the document body.", "Do not propose mutual termination at any casualty level (seller form-to-final ask).", "Do not propose Seller retain both insurance proceeds AND Purchase Price.", "Business numbers, percentages, deadlines, caps, baskets, holdback amounts, lender terms, tenant amounts, district facts, utility costs, and construction milestones are NEVER invented. Existing source numbers stay unless the rubric clearly authorizes a first-pass change."], "rule_promotion": {"AUTO": "Rubric-backed first-pass rule with a clean source trigger and no side conflict. Make the tracked edit if the section supplies an anchor. No discretion.", "AUTO_WITH_GATE": "Repeatable pattern with a clear trigger but fact-sensitive or placement-sensitive. Edit only after confirming the source trigger and side posture.", "FLAG_ONLY": "Final-form pattern, economics-heavy term, missing fact, leverage-dependent move, absent exhibit, or non-rubric judgment issue. Do not invent numbers. Surface as a judgment_item.", "ASK_FIRST": "One answer changes specific text. Surface as a judgment_item — never default-fill.", "REJECT": "Conflicts with rubric, client side, a hard block, first-pass posture, or document facts. Do not emit and do not flag."}, "first_pass_exclusions": ["Late-round damages carve-outs (fraud, willful default exceptions to consequential waiver).", "Late-round cap and basket compromises.", "Late-round specific-performance carve-outs / filing-deadline trades.", "Late-round assignment release compromises.", "Late-round Seller estoppel substitute concessions."], "authorized_signatory": {"allowed_blocks_seller_only": ["PSA Seller signature block", "Special Warranty Deed Grantor signature", "FIRPTA / Non-Foreign Affidavit Seller signature", "Bill of Sale Assignor signature", "Assignment of Leases / Resident Agreements Assignor signature", "Assignment of Contracts Assignor signature", "Assignment of Intangibles Assignor signature", "Owner's Affidavit Owner signature"], "forbidden_blocks": ["Buyer / Purchaser", "Grantee", "Assignee", "Escrow Agent", "Title Company", "Tenant / Resident", "Lender", "Broker", "Notary", "any third-party signatory"]}, "named_counsel_gate": "Never substitute a different attorney for the one named in the source Pivnick notice block. If a specific attorney is named, preserve verbatim. If blank, surface as a judgment_item — do not default-fill.", "notice_block_seller": "On seller side, PRESERVE whatever Pivnick address is already in source. Known variants: 'PO Box 670233, Dallas, TX 75367' and '5606 SMU Blvd #600009, Dallas, TX 75360-0009'. If both appear in different blocks, surface as a judgment_item — do not silently normalize. If blank, surface as a judgment_item.", "anchor_guidance": "When proposing an edit, the 'before' text must be copied verbatim from the section text provided, including exact punctuation, smart quotes, and spacing. Do not paraphrase the anchor. If you cannot find exact anchor text for an intended insertion, propose it as an insertion relative to a verbatim anchor sentence, or surface as a judgment_item."} as const;

export const ATTORNEY_PREFS = {"team_wide": ["No Word comments or commentary in the document body. ZERO. All commentary belongs in judgment_items for the end-of-run popup.", "Don't invent business numbers. When in doubt, surface as a judgment_item."], "rob-pivnick": {"name": "Rob Pivnick", "seller_notes": ["Seller-side notice block: HARD COPY, no email on first pass (make it harder for buyer; add email later only if buyer asks).", "Authorized Signatory convention applied on everything (Seller-aligned blocks only).", "Effective Date = last signature on seller side (not Title Company deposit convention)."]}, "jordan-bailey": {"name": "Jordan Bailey", "seller_notes": ["Strong on the §41-46 cluster: non-estate-property recital, no-financing-contingency carve, Seller-can-convey title fallback, Buyer/Seller conditions tightening, §17.1 deliverables scrubbing."]}, "will-tolliver": {"name": "Will Tolliver", "seller_notes": []}} as const;
